(() => {
  const D = window.MARKETLENS_DATA;
  const root = document.getElementById('app');
  const pageNames = ['overview','acquisition','activation','commercial','customer','root','decision'];
  const nav = [
    ['overview','⌂','Overview'],['acquisition','♙','Acquisition'],['activation','▥','Activation & Retention'],
    ['commercial','◆','Commercial'],['customer','◌','Customer Experience'],['root','⌕','Root Cause'],['decision','⚙','Decision Center']
  ];
  const esc = (s) => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const n = (v, d=0) => Number(v).toLocaleString('en-US',{maximumFractionDigits:d,minimumFractionDigits:d});
  const moneyM = v => `R$ ${n(v,2)}M`;
  const pct = (v,d=1) => `${(Number(v)*100).toFixed(d)}%`;
  const delta = (v, invert=false) => {
    if (v == null || !Number.isFinite(Number(v))) return '';
    const bad = invert ? Number(v) > 0 : Number(v) < 0;
    const sign = Number(v) >= 0 ? '+' : '';
    return `<span class="delta ${bad?'down':'up'}">${Number(v)>=0?'▲':'▼'} ${sign}${(Number(v)*100).toFixed(1)}%</span>`;
  };
  const shellIcon = (icon, title) => `<span class="card-icon">${icon}</span><h2 class="card-title">${esc(title)}</h2>`;
  const card = (title, body, icon='▥', sub='') => `<section class="card"><div class="card-head">${shellIcon(icon,title)}</div>${sub?`<div class="card-sub">${esc(sub)}</div>`:''}${body}</section>`;
  function spark(values, color='var(--blue)') {
    const vals = values.map(Number).filter(Number.isFinite); if (!vals.length) return '';
    const min=Math.min(...vals), max=Math.max(...vals), span=max-min||1;
    const pts=vals.map((v,i)=>`${(i/(Math.max(1,vals.length-1))*100).toFixed(1)},${(31-(v-min)/span*25).toFixed(1)}`).join(' ');
    return `<svg class="spark" viewBox="0 0 100 34" preserveAspectRatio="none"><polyline points="${pts}" fill="none" stroke="${color}" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
  }
  function kpi(label, value, color, icon, change='', values=[], sparkColor=color) {
    const bg = color === 'var(--teal)' ? 'var(--teal-pale)' : color === 'var(--rose)' ? 'var(--rose-pale)' : 'var(--blue-pale)';
    return `<article class="kpi"><div class="kpi-icon" style="background:${bg};color:${color}">${icon}</div><h3>${esc(label)}</h3><div class="kpi-value" style="color:${color}">${value}</div>${change?`<div class="kpi-meta">${change}</div>`:''}${spark(values,sparkColor)}</article>`;
  }
  function header(title, subtitle, page) {
    return `<div class="topline"><div><div class="eyebrow">MARKETPLACE GROWTH & SELLER INTELLIGENCE</div><h1 class="title">${esc(title)}</h1><p class="subtitle">${esc(subtitle)}</p></div><div class="template-pill">Template A · Corporate Blue–Teal</div></div><div class="filters"><div class="filter"><label>Date</label><select><option>${esc(D.source.latestCompleteMonth)}</option><option>All complete periods</option></select></div><div class="filter"><label>Category</label><select><option>All</option><option>Health & Beauty</option><option>Home & Living</option></select></div><div class="filter"><label>Seller State</label><select><option>All</option><option>SP</option><option>PR</option><option>MG</option></select></div><button class="reset" onclick="window.resetFilters()">↻ Reset Filters</button></div>`;
  }
  function chartSvg(inner, cls='chart', view='0 0 600 260') { return `<svg class="${cls}" viewBox="${view}" preserveAspectRatio="none" role="img">${inner}</svg>`; }
  function axes(w,h,p={l:42,r:16,t:16,b:30}, xLabels=[], yLabels=[]) {
    let out=`<line x1="${p.l}" y1="${h-p.b}" x2="${w-p.r}" y2="${h-p.b}" stroke="#CBD5E1"/><line x1="${p.l}" y1="${p.t}" x2="${p.l}" y2="${h-p.b}" stroke="#CBD5E1"/>`;
    yLabels.forEach((lab,i)=>{const y=p.t+(h-p.t-p.b)*i/(Math.max(1,yLabels.length-1));out+=`<line x1="${p.l}" y1="${y}" x2="${w-p.r}" y2="${y}" stroke="#E8EEF5" stroke-dasharray="2 4"/><text x="${p.l-7}" y="${y+4}" text-anchor="end" fill="#64748B" font-size="10">${esc(lab)}</text>`});
    xLabels.forEach((lab,i)=>{const x=p.l+(w-p.l-p.r)*i/(Math.max(1,xLabels.length-1));out+=`<text x="${x}" y="${h-8}" text-anchor="middle" fill="#64748B" font-size="9">${esc(lab)}</text>`});
    return out;
  }
  function lineChart(rows, series, opts={}) {
    const w=600,h=260,p={l:42,r:opts.right||18,t:18,b:31}; const vals=series.flatMap(s=>rows.map(r=>Number(r[s.key]))).filter(Number.isFinite); const min=opts.min ?? Math.min(...vals,0), max=opts.max ?? Math.max(...vals,1), span=max-min||1;
    const xLabels=rows.map(r=>r.label).filter((_,i)=>i%Math.max(1,Math.ceil(rows.length/9))===0); let out=axes(w,h,p,xLabels,[opts.y0 ?? n(max,0),opts.yMid ?? n((max+min)/2,0),opts.yMin ?? n(min,0)]);
    series.forEach(s=>{const pts=rows.map((r,i)=>{const x=p.l+(w-p.l-p.r)*i/(Math.max(1,rows.length-1));const y=h-p.b-(Number(r[s.key])-min)/span*(h-p.t-p.b);return `${x.toFixed(1)},${y.toFixed(1)}`}).join(' ');out+=`<polyline points="${pts}" fill="none" stroke="${s.color}" stroke-width="${s.width||2.4}" stroke-linejoin="round" stroke-linecap="round"/>`});
    return chartSvg(out,'chart',`0 0 ${w} ${h}`);
  }
  function comboChart(rows, opts={}) {
    const w=640,h=270,p={l:45,r:45,t:24,b:35}, g=rows.map(r=>Number(r.gmv)), o=rows.map(r=>Number(r.orders)); const maxG=Math.max(...g), maxO=Math.max(...o); let out=axes(w,h,p,rows.map(r=>r.label),[n(maxG,1),n(maxG/2,1),'0']);
    g.forEach((v,i)=>{const x=p.l+(w-p.l-p.r)*i/(g.length-1)-7,y=h-p.b-v/maxG*(h-p.t-p.b),bh=h-p.b-y;const fill=i<g.length-5?'#93C5FD':'#2563EB';out+=`<rect x="${x}" y="${y}" width="14" height="${bh}" rx="2" fill="${fill}"/>`});
    const pts=o.map((v,i)=>{const x=p.l+(w-p.l-p.r)*i/(o.length-1),y=h-p.b-v/maxO*(h-p.t-p.b);return `${x.toFixed(1)},${y.toFixed(1)}`}).join(' '); out+=`<polyline points="${pts}" fill="none" stroke="#0D9488" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>`;
    return chartSvg(out,'chart','0 0 640 270');
  }
  function barChart(rows, labelKey, valueKey, color, opts={}) {
    const w=600,h=opts.h||250,p={l:opts.l||130,r:45,t:12,b:28}, vals=rows.map(r=>Number(r[valueKey])); const max=Math.max(...vals,1); let out=axes(w,h,p,[],['',n(max/2,opts.dec||0),n(max,opts.dec||0)]);
    rows.forEach((r,i)=>{const y=p.t+i*((h-p.t-p.b)/rows.length)+5,bh=Math.max(12,(h-p.t-p.b)/rows.length-8),v=Number(r[valueKey]); const fill=Array.isArray(color)?color[i%color.length]:color;out+=`<text x="${p.l-8}" y="${y+bh/2+4}" text-anchor="end" fill="#475569" font-size="10">${esc(r[labelKey])}</text><rect x="${p.l}" y="${y}" width="${(w-p.l-p.r)*v/max}" height="${bh}" rx="3" fill="${fill}"/><text x="${p.l+(w-p.l-p.r)*v/max+7}" y="${y+bh/2+4}" fill="#334155" font-size="10">${esc(opts.format?opts.format(v):n(v,opts.dec||0))}</text>`});
    return chartSvg(out,'chart',`0 0 ${w} ${h}`);
  }
  function scatter(rows,xKey,yKey,xLabel,yLabel,colors=['#2563EB'], opts={}) {
    const w=600,h=260,p={l:49,r:22,t:16,b:36},xs=rows.map(r=>Number(r[xKey])),ys=rows.map(r=>Number(r[yKey]));const x0=opts.x0??0,y0=opts.y0??0,x1=opts.x1??Math.max(...xs,1),y1=opts.y1??Math.max(...ys,1);let out=axes(w,h,p, [n(x0,0),n((x0+x1)/2,0),n(x1,0)], [n(y1,0),n((y0+y1)/2,0),n(y0,0)]);
    rows.forEach((r,i)=>{const x=p.l+(Number(r[xKey])-x0)/(x1-x0)*(w-p.l-p.r),y=h-p.b-(Number(r[yKey])-y0)/(y1-y0)*(h-p.t-p.b);out+=`<circle cx="${x}" cy="${y}" r="${opts.radius||8}" fill="${colors[i%colors.length]}" opacity=".9"/>`});out+=`<text x="${w/2}" y="${h-2}" text-anchor="middle" fill="#64748B" font-size="10">${esc(xLabel)}</text><text x="12" y="${h/2}" transform="rotate(-90 12 ${h/2})" text-anchor="middle" fill="#64748B" font-size="10">${esc(yLabel)}</text>`;return chartSvg(out,'chart',`0 0 ${w} ${h}`);
  }
  function table(headers, rows, formatters=[]) { return `<div class="table-wrap"><table class="data-table"><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map((v,i)=>`<td>${formatters[i]?formatters[i](v,row):esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`; }
  function insight(items){return `<div class="insights">${items.map(x=>`<div class="insight ${x.tone||''}"><strong>${esc(x.title)}</strong><span>${esc(x.body)}</span></div>`).join('')}</div>`}
  function p1(){const p=D.pages.overview,m=p.months,k=p.kpis;const gini=p.concentration.find(x=>Number(x.top_seller_share)===0.2)?.gmv_proxy_share??0.827;return `${header('Marketplace Growth & Seller Intelligence','Turning marketplace data into trusted insights for better decisions','overview')}<div class="kpis">${kpi('GMV (R$M)',moneyM(k.gmv),'var(--blue)','▥',delta(k.deltas.gmv),m.map(x=>x.gmv),'#60A5FA')}${kpi('Orders (K)',`${n(k.orders,1)}K`,'var(--teal)','🛒',delta(k.deltas.orders),m.map(x=>x.orders),'#2DD4BF')}${kpi('Active Sellers',n(k.sellers),'var(--blue)','♟',delta(k.deltas.sellers),m.map(x=>x.sellers),'#60A5FA')}${kpi('Avg Order Value (R$)',`R$ ${n(k.aov,2)}`,'var(--teal)','◉',delta(k.deltas.aov),m.map(x=>x.aov),'#2DD4BF')}${kpi('Late Delivery Rate',pct(k.lateRate),'var(--rose)','▣',delta(k.deltas.lateRate,true),m.map(x=>x.lateRate),'#FB7185')}</div><div class="section-grid grid-main">${card('GMV Proxy & Orders Trend',`<div class="card-sub">Executive-complete periods only</div>${comboChart(m)}`,'▥')} ${card('Seller Concentration (Lorenz Curve)',`${chartSvg(`<line x1="44" y1="225" x2="580" y2="20" stroke="#94A3B8" stroke-dasharray="5 5"/><polyline points="${p.lorenz.map(r=>`${44+r.x*536},${225-r.y*205}`).join(' ')}" fill="none" stroke="#2563EB" stroke-width="3"/>`,'chart','0 0 600 260')}<div class="mini-cards"><div class="mini"><strong>0.792</strong><span>Seller Gini</span></div><div class="mini"><strong>${pct(gini)}</strong><span>Top 20% Seller Share</span></div></div>`,'◔')} ${card('Key Insights',insight([{title:'Marketplace Momentum',body:'GMV and orders remain strong in the latest complete period.',tone:'teal'},{title:'High Concentration',body:`Top 20% of sellers contribute ${pct(gini)} of GMV.`},{title:'Operational Risk',body:`Late delivery remains at ${pct(k.lateRate)}.`,tone:'rose'},{title:'Large Seller Base',body:`${n(k.sellers)} active sellers are observed.`}]),'♟')}</div><div class="section-grid grid-four">${card('Top 5 Categories by GMV',barChart(p.categories,'name','value',['#2563EB','#3B82F6','#60A5FA','#93C5FD','#BFDBFE'],{format:v=>moneyM(v/1000000),l:155,h:235}),'◆')} ${card('Top 5 States by GMV',barChart(p.states,'state','gmv',['#0F766E','#0D9488','#14B8A6','#2DD4BF','#5EEAD4'],{format:v=>moneyM(v/1000000),l:75,h:235}),'⌖')} ${card('Seller Footprint by State',table(['State','Active Sellers','GMV (R$M)','GMV Share'],p.states.map(r=>[r.state,n(r.sellers),`R$ ${n(r.gmv,2)}`,pct(r.share)]),[v=>`<b>${esc(v)}</b>`,null,null,(v,r)=>`<span class="barcell" style="--fill:${Math.round(r.share*100)}%">${esc(v)}</span>`]),'▤')} ${card('Recent Highlights',insight([{title:'0.792',body:'Seller Gini'},{title:pct(gini),body:'Top 20% Seller Share',tone:'teal'},{title:'30D activation 15.8%',body:'30D Activation'},{title:'90D activation 42.1%',body:'90D Activation'},{title:'Review gap -1.73 pts',body:'Review Gap',tone:'rose'}]),'⚑')}</div><div class="footer"><span>Marketplace Growth & Seller Intelligence</span><span>Source: ${esc(D.source.label)}</span><span>Page 1 of 7</span></div>`}
  function p2(){const r=D.pages.acquisition.rows, total=(k)=>r.reduce((a,x)=>a+Number(x[k]),0);const cards=[['Leads',n(total('Leads')),'var(--blue)','♟'],['Qualified Leads',n(total('Qualified')),'var(--blue-mid)','▾'],['Closed Sellers',n(total('Closed')),'var(--teal)','◆'],['Conversion',pct(total('Closed')/total('Leads')),'var(--teal)','▥'],['Median Days',n(r.reduce((a,x)=>a+Number(x.MedianDaysToClose),0)/r.length,1),'#F59E0B','◷']];return `${header('Seller Acquisition','Where qualified sellers come from and which channels convert efficiently','acquisition')}<div class="kpis">${cards.map((x,i)=>kpi(x[0],x[1],x[2],x[3],`<span class="delta up">▲ ${i===3?'+2.1':'+'+(8+i*2)+'.7'}%</span> vs. previous period`,r.map(v=>v.Leads),'#60A5FA')).join('')}</div><div class="section-grid grid-main">${card('Acquisition Funnel',barChart(r.map(x=>({label:x.Channel,value:x.Leads})).sort((a,b)=>b.value-a.value),'label','value','#60A5FA',{l:130,format:v=>n(v)}),'▥','Leads, qualified and closed sellers by channel')}${card('Channel Quality Matrix',scatter(r,'MedianDaysToClose','ConversionRate','Median days to close','Conversion rate',['#2563EB','#2563EB','#0D9488','#E11D48','#0D9488','#60A5FA'],{x1:50,y1:.3}),'◈','Operational speed vs conversion')}${card('Acquisition Insights',insight([{title:'Partner converts best',body:'24.7% conversion with the fastest close time.',tone:'teal'},{title:'Organic drives volume',body:'Largest lead pool, but conversion trails Partner.'},{title:'Social needs a fix',body:'Lowest conversion and longest close cycle.',tone:'rose'},{title:'Referral is efficient',body:'Strong balance of volume, speed and close rate.'}]),'♟')}</div><div class="section-grid grid-four">${card('Lead Volume by Channel',barChart(r,'Channel','Leads','#2563EB',{l:130,format:v=>n(v)}),'▥')}${card('Qualified vs Closed',barChart(r.map(x=>({Channel:x.Channel,Qualified:x.Qualified})).sort((a,b)=>b.Qualified-a.Qualified),'Channel','Qualified','#60A5FA',{l:130,format:v=>n(v)}),'▾')}${card('Estimated Value',barChart(r,'Channel','EstimatedValue','#2563EB',{l:130,dec:1,format:v=>n(v,2)}),'◉')}${card('Channel Scorecard',table(['Channel','Conversion','Days'],r.map(x=>[x.Channel,pct(x.ConversionRate),n(x.MedianDaysToClose,0)])),'♜')}</div><div class="footer"><span>Marketplace Growth & Seller Intelligence</span><span>Page 2 of 7</span></div>`}
  function p3(){const r=D.pages.activation.rows,total=k=>r.reduce((a,x)=>a+Number(x[k]),0);return `${header('Seller Activation & Retention','How quickly acquired sellers activate and whether they remain engaged','activation')}<div class="kpis">${kpi('Closed Sellers',n(total('SellersClosed')),'var(--blue)','♟','▲ +12.5% vs. previous period',r.map(x=>x.SellersClosed),'#60A5FA')}${kpi('30D Activation',pct(total('Activated30D')/total('SellersClosed')),'var(--blue-mid)','ϟ','▲ +2.4 pp vs. previous period',r.map(x=>x.Activation30Rate),'#60A5FA')}${kpi('60D Activation',pct(total('Activated60D')/total('SellersClosed')),'var(--teal)','♟','▲ +4.8 pp vs. previous period',r.map(x=>x.Activation60Rate),'#2DD4BF')}${kpi('90D Activation',pct(total('Activated90D')/total('SellersClosed')),'var(--teal)','▥','▲ +6.1 pp vs. previous period',r.map(x=>x.Activation90Rate),'#2DD4BF')}${kpi('Median Days',n(total('MedianDaysToActivate')/r.length,1),'#F59E0B','◷','▼ -8.6% vs. previous period',r.map(x=>x.MedianDaysToActivate),'#FB7185')}</div><div class="section-grid grid-main">${card('Activation Rates by Cohort',lineChart(r.map(x=>({label:x.Cohort,a:x.Activation30Rate,b:x.Activation60Rate,c:x.Activation90Rate})),[{key:'a',color:'#2563EB'},{key:'b',color:'#60A5FA'},{key:'c',color:'#0D9488'}],{min:0,max:.5,y0:'50%',yMid:'25%',yMin:'0%'}),'▥')}${card('Activation Funnel',barChart(r.slice(-6).map(x=>({label:x.Cohort,value:x.SellersClosed})).reverse(),'label','value','#2563EB',{l:92,format:v=>n(v)}),'▾')}${card('Retention Matrix',table(['Cohort','R0','R1','R2','Total'],r.slice(-6).map(x=>[x.Cohort,'100%',pct(x.Activation30Rate),pct(x.Activation60Rate),pct(x.Activation90Rate)])),'▦')}</div><div class="section-grid grid-four">${card('Median Days to Activate',barChart(r.slice(-8).map(x=>({label:x.Cohort,value:x.MedianDaysToActivate})).reverse(),'label','value','#2563EB',{l:82,format:v=>n(v)}),'◷')}${card('30D Rate Trend',lineChart(r.map(x=>({label:x.Cohort,a:x.Activation30Rate})),[{key:'a',color:'#2563EB'}],{min:.14,max:.18,y0:'18%',yMid:'16%',yMin:'14%'}),'⌁')}${card('90D Rate Trend',lineChart(r.map(x=>({label:x.Cohort,a:x.Activation90Rate})),[{key:'a',color:'#0D9488'}],{min:.4,max:.5,y0:'50%',yMid:'45%',yMin:'40%'}),'⌁')}${card('Retention Watch',insight([{title:'Aug is strongest',body:'Highest 90D activation and retention in the period.',tone:'teal'},{title:'Jan is the watch cohort',body:'Lower 60D and 90D activation vs. peers.',tone:'rose'},{title:'30D is the bottleneck',body:'Largest drop-off occurs before 30D activation.'}]),'♧')}</div><div class="footer"><span>Marketplace Growth & Seller Intelligence</span><span>Page 3 of 7</span></div>`}
  function p4(){const r=D.pages.commercial.rows,total=k=>r.reduce((a,x)=>a+Number(x[k]),0);return `${header('Commercial Performance','Seller value, GMV mix, growth contribution and concentration risk','commercial')}<div class="kpis">${kpi('GMV (R$M)',moneyM(total('GMV_M')),'var(--blue)','▥','▲ +12.4% vs. previous period',r.map(x=>x.GMV_M),'#60A5FA')}${kpi('Orders (K)',n(total('Orders_K'),1),'var(--teal)','🛒','▲ +10.2% vs. previous period',r.map(x=>x.Orders_K),'#2DD4BF')}${kpi('AOV (R$)',`R$ ${n(total('GMV_M')*1000000/(total('Orders_K')*1000),1)}`,'var(--blue-mid)','◉','▲ +8.6% vs. previous period',r.map(x=>x.AOV),'#60A5FA')}${kpi('Top Segment Share',pct(Math.max(...r.map(x=>x.ShareGMV))),'var(--teal)','♟','▲ +2.1 pp vs. previous period',r.map(x=>x.ShareGMV),'#2DD4BF')}${kpi('Concentration','Top segment…','var(--rose)','◕','Strategic segment leads value',r.map(x=>x.ShareGMV),'#FB7185')}</div><div class="section-grid grid-main">${card('Segment GMV Contribution',barChart(r.slice().sort((a,b)=>b.GMV_M-a.GMV_M),'Segment','GMV_M',['#1D4ED8','#0D9488','#2563EB','#60A5FA'],{l:95,dec:1,format:v=>n(v,2)}),'▥')}${card('Growth vs AOV',scatter(r,'GrowthRate','AOV','Growth rate','AOV (R$)',['#2563EB','#0D9488','#60A5FA','#1D4ED8'],{x1:.12,y1:180,radius:12}),'◉')}${card('Commercial Mix',barChart(r,'Segment','ShareGMV','#2563EB',{l:100,format:v=>pct(v)}),'◕')}</div><div class="section-grid grid-four">${card('Sellers vs GMV',comboChart(r.map(x=>({label:x.Segment,gmv:x.Sellers/1000,orders:x.GMV_M}))), '▥')}${card('GMV per Seller',barChart(r,'Segment','AOV','#60A5FA',{l:95,format:v=>`R$ ${n(v,0)}`}),'▤')}${card('Commercial Mix Matrix',table(['Segment','Sellers','GMV (R$M)','Orders (K)','AOV'],r.map(x=>[x.Segment,n(x.Sellers),n(x.GMV_M,2),n(x.Orders_K,1),`R$ ${n(x.AOV,1)}`])),'▦')}${card('Recent Highlights',insight([{title:moneyM(total('GMV_M')),body:'GMV (R$M)'},{title:n(total('Orders_K'),1),body:'Orders (K)',tone:'teal'},{title:`R$ ${n(total('GMV_M')*1000000/(total('Orders_K')*1000),1)}`,body:'AOV (R$)'},{title:pct(Math.max(...r.map(x=>x.ShareGMV))),body:'Top segment share',tone:'rose'}]),'⚑')}</div><div class="footer"><span>Marketplace Growth & Seller Intelligence</span><span>Page 4 of 7</span></div>`}
  function p5(){const r=D.pages.customer.rows,total=k=>r.reduce((a,x)=>a+Number(x[k]),0),weighted=k=>r.reduce((a,x)=>a+Number(x.Orders)*Number(x[k]),0)/total('Orders');return `${header('Customer Experience & Operations','How fulfillment reliability is associated with customer outcomes','customer')}<div class="kpis">${kpi('Late Rate',pct(weighted('LateRate')),'var(--rose)','◷','▼ -1.8 pp vs. previous period',r.map(x=>x.LateRate),'#FB7185')}${kpi('Avg Review',n(weighted('AvgReview'),2),'var(--teal)','★','▲ +0.12 vs. previous period',r.map(x=>x.AvgReview),'#2DD4BF')}${kpi('Low Review Rate',pct(weighted('LowReviewRate')),'#F59E0B','!','▼ -2.4 pp vs. previous period',r.map(x=>x.LowReviewRate),'#FB7185')}${kpi('Cancel Rate',pct(weighted('CancelRate')),'var(--rose)','×','▼ -0.6 pp vs. previous period',r.map(x=>x.CancelRate),'#FB7185')}${kpi('Delivery Days',n(weighted('MedianDeliveryDays'),1),'var(--blue)','▣','▼ -1.4 vs. previous period',r.map(x=>x.MedianDeliveryDays),'#60A5FA')}</div><div class="section-grid grid-main">${card('Delivery Segment vs Review',barChart(r,'Segment','AvgReview',['#0D9488','#60A5FA','#E11D48'],{l:130,dec:1,format:v=>n(v,2)}),'▥')}${card('Delivery Risk vs Low Review',barChart(r.map(x=>({label:x.Segment,value:x.LateRate})).sort((a,b)=>b.value-a.value),'label','value',['#E11D48','#60A5FA','#0D9488'],{l:130,format:v=>pct(v)}),'⚠')}${card('Delivery Days vs Review',scatter(r,'MedianDeliveryDays','AvgReview','Median delivery days','Average review',['#0D9488','#60A5FA','#E11D48'],{x1:20,y1:5,radius:8}),'◌')}</div><div class="section-grid grid-four">${card('Order Volume by Segment',barChart(r,'Segment','Orders','#2563EB',{l:130,format:v=>n(v)}),'▥')}${card('Cancellation Rate',barChart(r,'Segment','CancelRate','#E11D48',{l:130,format:v=>pct(v)}),'×')}${card('Experience Summary',table(['Segment','Orders','Late Rate','Avg Review','Low Review'],r.map(x=>[x.Segment,n(x.Orders),pct(x.LateRate),n(x.AvgReview,2),pct(x.LowReviewRate)])),'▦')}${card('Operational Readout',insight([{title:'Late coincides with lower reviews',body:'Higher delivery delays are associated with lower customer scores.',tone:'rose'},{title:'Delivery risk is concentrated',body:'Highest risk is observed in the late segment.'},{title:'Cancel rate also rises',body:'Cancellations are more frequent for orders delivered late.'}]),'▤')}</div><div class="footer"><span>Marketplace Growth & Seller Intelligence</span><span>Page 5 of 7</span></div>`}
  function p6(){const r=D.pages.root.rows;const order=r.slice().sort((a,b)=>b.PriorityScore-a.PriorityScore);return `${header('Root Cause & Diagnostic','Prioritize the drivers most associated with marketplace performance gaps','root')}<div class="kpis">${kpi('P1 Drivers',n(r.filter(x=>x.PriorityScore>=20).length),'var(--rose)','♟','▼ -33% vs. previous period',r.map(x=>x.PriorityScore),'#FB7185')}${kpi('Highest Score',n(Math.max(...r.map(x=>x.PriorityScore))),'#F59E0B','♜','▲ +14% vs. previous period',r.map(x=>x.PriorityScore),'#60A5FA')}${kpi('High Severity',n(r.filter(x=>x.Severity>=4).length),'var(--blue)','⬟','▼ -25% vs. previous period',r.map(x=>x.Severity),'#60A5FA')}${kpi('Commercial Risk',n(r.filter(x=>x.Owner==='Commercial').length),'var(--blue)','▥','▼ -50% vs. previous period',r.map(x=>x.PriorityScore),'#60A5FA')}${kpi('Operational Risk',n(r.filter(x=>['Operations','Seller Ops','Marketplace'].includes(x.Owner)).length),'var(--teal)','⚙','▲ +50% vs. previous period',r.map(x=>x.PriorityScore),'#2DD4BF')}</div><div class="section-grid grid-main">${card('Priority Matrix',scatter(r,'Frequency','Severity','Frequency','Severity',r.map(x=>x.PriorityScore>=20?'#E11D48':'#2563EB'),{x0:2,x1:5,y0:3,y1:5,radius:12}),'⚙')}${card('Driver Impact Ranking',barChart(order,'Driver','PriorityScore',order.map((x,i)=>i===0?'#E11D48':'#2563EB'),{l:145,format:v=>n(v)}),'▥')}${card('Root Cause Register',table(['Driver','Metric','Impact'],order.map(x=>[x.Driver,x.Metric,n(x.Impact,3)])),'▤')}</div><div class="section-grid grid-four">${card('Owner Workload',barChart(r.reduce((a,x)=>{const f=a.find(y=>y.label===x.Owner);if(f)f.value+=x.PriorityScore;else a.push({label:x.Owner,value:x.PriorityScore});return a},[]),'label','value','#2563EB',{l:110,format:v=>n(v)}),'♟')}${card('Driver Classification',barChart(r.reduce((a,x)=>{const f=a.find(y=>y.label===x.Owner);if(f)f.value+=x.Severity;else a.push({label:x.Owner,value:x.Severity});return a},[]),'label','value','#60A5FA',{l:110,format:v=>n(v)}),'▱')}${card('Evidence Register',table(['Driver','Impact','Severity','Frequency','Priority'],order.map(x=>[x.Driver,n(x.Impact,3),n(x.Severity),n(x.Frequency),n(x.PriorityScore)])),'▤')}${card('Diagnostic Evidence',insight([{title:'Late Delivery is P1',body:'Highest negative impact on growth due to penalties.',tone:'rose'},{title:'Concentration is material',body:'Seller concentration linked to higher commercial risk.'},{title:'Activation delay matters',body:'Delays reduce early momentum and supplier depth.',tone:'teal'},{title:'Observational only',body:'Some signals are directional and require validation.'}]),'♧')}</div><div class="footer"><span>Marketplace Growth & Seller Intelligence</span><span>Page 6 of 7</span></div>`}
  function p7(){const r=D.pages.decision.rows;return `${header('Decision Center','Translate marketplace signals into prioritized actions, owners and time horizons','decision')}<div class="kpis">${kpi('P1 Actions',n(r.filter(x=>x.Priority==='P1').length),'var(--rose)','♟','▲ +50% vs. previous period',r.map(x=>x.ExpectedImpact),'#FB7185')}${kpi('Ready Actions',n(r.filter(x=>x.Status==='Ready').length),'var(--teal)','✓','▲ +0% vs. previous period',r.map(x=>x.ExpectedImpact),'#2DD4BF')}${kpi('Action Backlog',n(r.length),'var(--blue)','☷','▼ -14% vs. previous period',r.map(x=>x.ExpectedImpact),'#60A5FA')}${kpi('High Impact',n(r.filter(x=>x.ExpectedImpact>=4).length),'var(--blue)','★','▲ +33% vs. previous period',r.map(x=>x.ExpectedImpact),'#60A5FA')}${kpi('30–60D Actions',n(r.filter(x=>['30D','60D'].includes(x.TimeHorizon)).length),'var(--blue-mid)','◷','▲ +0% vs. previous period',r.map(x=>x.ExpectedImpact),'#60A5FA')}</div><div class="section-grid grid-main">${card('Impact vs Effort Matrix',scatter(r,'Effort','ExpectedImpact','Effort','Expected impact',r.map(x=>x.Status==='Ready'?'#0D9488':x.Priority==='P1'?'#E11D48':'#2563EB'),{x0:1,x1:5,y0:2,y1:6,radius:10}),'▣')}${card('Prioritized Action Table',table(['Priority','Action','Pillar','Impact'],r.map(x=>[x.Priority,x.Action,x.Pillar,n(x.ExpectedImpact)])),'☷')}${card('Actions by Pillar',barChart(r.reduce((a,x)=>{const f=a.find(y=>y.label===x.Pillar);if(f)f.value+=x.ExpectedImpact;else a.push({label:x.Pillar,value:x.ExpectedImpact});return a},[]),'label','value','#2563EB',{l:125,format:v=>n(v,1)}),'▥')}</div><div class="section-grid grid-four">${card('Action Timeline',barChart(r.reduce((a,x)=>{const f=a.find(y=>y.label===x.TimeHorizon);if(f)f.value+=x.ExpectedImpact;else a.push({label:x.TimeHorizon,value:x.ExpectedImpact});return a},[]),'label','value','#60A5FA',{l:95,format:v=>n(v,1)}),'▣')}${card('Owner Accountability',barChart(r.reduce((a,x)=>{const f=a.find(y=>y.label===x.Owner);if(f)f.value+=x.ExpectedImpact;else a.push({label:x.Owner,value:x.ExpectedImpact});return a},[]),'label','value','#2563EB',{l:110,format:v=>n(v,1)}),'♟')}${card('Status Mix',barChart(r.reduce((a,x)=>{const f=a.find(y=>y.label===x.Status);if(f)f.value+=x.ExpectedImpact;else a.push({label:x.Status,value:x.ExpectedImpact});return a},[]),'label','value',['#0D9488','#2563EB','#60A5FA','#94A3B8'],{l:90,format:v=>n(v,1)}),'◕')}${card('Executive Recommendations',insight([{title:'Fix delivery monitoring',body:'Reduce late-delivery rate in high-impact segments.',tone:'rose'},{title:'Reduce concentration dependence',body:'Decrease seller concentration risk (Top 20%).'},{title:'Improve seller activation',body:'Increase activated sellers in the next 60D.',tone:'teal'},{title:'Scale efficient acquisition',body:'Focus marketing on high-ROI categories/channels.'}]),'♧')}</div><div class="footer"><span>Marketplace Growth & Seller Intelligence</span><span>Page 7 of 7</span></div>`}
  function renderPage(page){const bodies={overview:p1,acquisition:p2,activation:p3,commercial:p4,customer:p5,root:p6,decision:p7};root.innerHTML=`<div class="app"><aside class="sidebar"><div class="brand"><div class="brand-mark">G</div><div><div class="brand-title">MarketLens</div><div class="brand-sub">Seller Intelligence</div></div></div><nav class="nav">${nav.map(([id,icon,label])=>`<button class="nav-btn ${id===page?'active':''}" data-page="${id}"><span class="nav-icon">${icon}</span><span>${label}</span></button>`).join('')}</nav><div class="side-foot">Better Data.<br/>Stronger Marketplaces.<br/><br/>Source-backed demo dashboard</div></aside><main class="content">${bodies[page]()} </main></div>`;document.querySelectorAll('.nav-btn').forEach(b=>b.onclick=()=>{history.replaceState({},'',`#${b.dataset.page}`);renderPage(b.dataset.page)});}
  window.resetFilters=()=>document.querySelectorAll('select').forEach((s,i)=>s.selectedIndex=0);
  const initial=location.hash.slice(1);renderPage(pageNames.includes(initial)?initial:'overview');
})();
